-- Bootstrap reviewed local preview assets with their original provenance; official-source verification is still pending.
-- Existing logo histories, including removals, are never overwritten.
INSERT INTO school_logo_versions(school_id,version,bytes,sha256,width,height,source_url,source_note)
SELECT s.id,1,decode('','base64'),'f20edbc6469abe96208c514ef61bb8a981405c0864b274b00ae78fd388799f91',250,251,'https://commons.wikimedia.org/wiki/File:Tsinghua_University_Logo.svg','Existing preview asset migrated to school-managed storage. Source: https://en.wikipedia.org/wiki/Tsinghua_University. Official-source verification remains pending; do not label as officially verified.'
FROM schools s WHERE s.slug = 'tsinghua-university' AND s.status <> 'archived'
AND NOT EXISTS (SELECT 1 FROM school_logo_versions existing WHERE existing.school_id=s.id)
ON CONFLICT DO NOTHING;
--> statement-breakpoint
